package main

import (
	"errors"
	"regexp"
)

// attributionTools names the AI tools and vendors a commit or pull request
// must not credit. .githooks/commit-msg carries the same list.
const attributionTools = `claude|anthropic|cursor|codex|openai|copilot|kiro|gemini|glm|kimi|opencode|agy`

// attributionPattern matches a Co-authored-by trailer naming an AI tool, a
// "Generated with" or "Generated by" line naming one (or just AI), and the
// robot emoji. Names match as whole words, so a human named Maggy passes.
var attributionPattern = regexp.MustCompile(
	`(?im)co-authored-by:.*[^a-z0-9](` + attributionTools + `)([^a-z0-9]|$)` +
		`|generated (with|by).*[^a-z0-9](` + attributionTools + `|ai)([^a-z0-9]|$)` +
		"|\U0001F916",
)

var errAttribution = errors.New("AI or tool attribution is not allowed")

// checkAttribution returns an error when text credits an AI tool.
func checkAttribution(text string) error {
	if attributionPattern.MatchString(text) {
		return errAttribution
	}
	return nil
}
